    mcq1: ["How does the Lord's Prayer begin in Matthew 6:9?", ["Our Father in heaven", "Almighty Lord", "Holy God", "Great King"], 0, "Jesus taught us to say, Our Father in heaven."],
    mcq2: ["What does the Spirit enable believers to cry in Romans 8:15?", ["Abba! Father!", "Holy! Holy!", "Mercy!", "Hosanna!"], 0, "By the Spirit we cry, Abba! Father!"],
